  const rows = [];
  for (const [phase, ids] of Object.entries(phaseGroups)) {
    const cfg = phaseConfig[phase];
    if (!cfg) throw new Error(`Missing reviewed phase config ${phase}`);
    for (const id of ids) rows.push({
      id,
      owningPhases: [phase],
      dependencies: cfg.dependencies,
      dependenciesVerified: true,
      applicableCompaniesOrCapabilities: ['Command Center', cfg.capability],
      implementationLocations: cfg.locations,
      tests: {
        positive: { applicable: true, references: [t(cfg.tests[0])], justification: null },
        negative: { applicable: true, references: [t(cfg.tests[1])], justification: null },
        failurePath: { applicable: true, references: [t(cfg.tests[2])], justification: null }
      },
      evidence: [provenanceFor(phase)],
      closureNotes: `Individually reviewed canonical requirement assigned to ${phase}; guarded exact-head qualification must prove current implementation/test references before promotion.`
    });
  }
  return rows;
